export const rateCases=[{id:'gas',title:'Gas collected',quantity:'Gas volume / cm³',unit:'cm³/s',start:0,end:48,t0:0,t1:24,used:false},{id:'interval',title:'A later interval',quantity:'Gas volume / cm³',unit:'cm³/s',start:12,end:36,t0:10,t1:30,used:false},{id:'mass',title:'Reactant consumed',quantity:'Reactant mass / g',unit:'g/s',start:5,end:3.8,t0:0,t1:60,used:true}];
export function meanAccount(t){const change=t.used?t.start-t.end:t.end-t.start,elapsed=t.t1-t.t0;if(!(elapsed>0)||change<0)throw Error('Expected positive elapsed time and nonnegative quantity change');return {change,elapsed,rate:change/elapsed};}
const near=(v,n)=>String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)-n)<=Math.max(.000001,Math.abs(n)*.001);
export const meanCorrect=(t,a)=>Object.entries(meanAccount(t)).every(([k,v])=>near(a[k],v));
export const collisionCases=[{id:'concentration',title:'More concentrated solution',prompt:'Double reactant particle count in the same volume at the same temperature. Predict the rate direction, keeping other relevant conditions fixed.',change:'More particles',reason:'frequency'},{id:'pressure',title:'Compress the reacting gas',prompt:'Keep gas particle count and temperature fixed, but halve the volume. Predict the rate direction.',change:'Smaller volume',reason:'frequency'},{id:'temperature',title:'Raise the temperature',prompt:'Keep concentration and reaction pathway fixed, but increase temperature. Predict the rate direction.',change:'Faster particles',reason:'energy'},{id:'surface',title:'Break the solid into pieces',prompt:'Cut one solid cube into eight equal smaller cubes. Keep total solid volume and other conditions fixed. Predict the rate direction.',change:'More exposed surface',reason:'surface'}];
export const collisionCorrect=(t,a)=>a.rate==='faster'&&a.reason===t.reason;
